  // that check pins the two together — a scope this declaration hands out but the
  // gate then refuses is the failure the pin exists for.
  //
  // The title is the pinned commit subject that gate keys on, which is also why the
  // previous round is recognisable from its PR alone.
  preconditions: [
    'substantive-change',
    'commits-outside:.claudinite/',
    'no-open-pr-titled:Claudinite tidy: improve comments',
  ],
  agent_model: 'opus',                   // whether a comment carries a why the code cannot state is the judgment here, and a wrong call lands in the repo's source
  // A ceiling, not a plan: the repo's own delivery setting decides whether the
  // PR lands unreviewed, and a `review` member still gets it left open. The
  // policy states in the contract what makes the pass safe to land unattended —
  // the diff can only ever be comment text and README content — and the pass's
  // own scope gate (the skill's `improve-comments-scope` check) reds the same
  // boundary on every branch wearing its title, armed or not.
  expected_outcome: 'pr',
  automerge: ['comment-only-changes', 'readme-changes'],
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,
};
---
// growth-promote's own precondition term: which members changed the local packs
// this run would read. The fleet aggregate is a canon-only signal over a wider
// credential, and the participation rule (declare claudinite-growth, and do not
// opt out of promotion) is this task's alone — so both live beside its
// declaration rather than in the shared vocabulary.

export const terms = {
  'fleet-local-packs-changed': {
    signals: ['fleet'],
    holds(signals) {
      const fleet = signals.fleet;
      // NOT a decline. A missing credential or a failed enumeration is a read this
      // run could not make, and promoting nothing on unproven fleet state looks
      // exactly like a fleet with nothing to promote — permanently, and silently.
      if (!fleet) return { error: 'no fleet signal — FLEET_GITHUB_TOKEN is unset, or this repo is not a canon home' };
      if (fleet.error) return { error: `fleet enumeration failed — ${fleet.error}` };

      // A participant declares claudinite-growth; the growth entry's
      // `{ config: { promote: false } }` opts a member out of promotion while it
      // keeps extracting and deduping locally (absent or true = participate).
      const changed = (fleet.members ?? [])
        .filter((m) => m.activePacks.includes('claudinite-growth'))
        .filter((m) => m.packConfigs?.['claudinite-growth']?.promote !== false)
        .filter((m) => m.localPacksChanged);
      if (!changed.length) return { holds: false, reason: 'no participating member changed its local packs in the window' };
      const repos = changed.map((m) => m.repo);
      return {
        holds: true,
        reason: `${changed.length} participating member(s) changed their local packs in the window`,
        context: [
          `Target members (local packs changed in the window): ${repos.join(', ')}.`,
          'Read ONLY these members\' local packs — do not enumerate the fleet yourself or widen past this list.',
        ],
      };
    },
  },
};
---
// store-release's own precondition term: an unreleased manifest bump. It compares
// two facts nothing else in the vocabulary knows about each other — the shipped
// manifest version and the latest published release tag — so it lives beside the
// declaration that names it.

// Tags and manifest versions are compared modulo a leading `v`.
const norm = (v) => String(v ?? '').replace(/^v/, '').trim();

export const terms = {
  'manifest-ahead': {
    signals: ['release'],
    holds(signals) {
      const rel = signals.release ?? {};
      const shipped = norm(rel.manifestVersion);
      const released = norm(rel.latestTag);
      if (shipped === '') return { holds: false, reason: 'no manifest version could be read to compare against the latest release' };
      if (shipped === released) return { holds: false, reason: `manifest ${shipped} matches the latest release` };
      return {
        holds: true,
        reason: released ? `manifest ${shipped} is ahead of released ${released}` : `manifest ${shipped}, and nothing released yet`,
      };
    },
  },
};

