############ ClaudiniteWebsite/site-stats
  // No gate. There is nothing to observe that would tell this task whether the
  // canon's counts moved — the answer IS the count, and the count is the run.
  //
  // What keeps that from being a weekly PR of noise is idempotence rather than a
  // precondition: the worker compares its recount against the page as it stands on
  // the base branch and delivers only a difference. "Recounted, the page was already
  // right, nothing delivered" is an empty outcome, not a skip.
  precondition() {
    return { run: true, reason: 'weekly recount of the canon-wide figures the site promotes' };
  },
};
############ EdFringeNow/refresh-shows

  // Unconditional — what a hand-pulled run gets, and what a restored cadence
  // would get. The thing this task reacts to — shows added or edited on
  // edfringe.com — leaves no trace in this repo, so there is no signal to
  // precondition on: the only honest gate is the cadence itself, exactly as the
  // retired daily cron was. The run is cheap and self-limiting (one paged
  // `recentlyAdded=LAST_SEVEN_DAYS` pass) and commits nothing when nothing moved.
  precondition() {
    return { run: true, reason: 'the top-up is unconditional — upstream show edits leave no signal in this repo' };
  },
};
############ EdFringeNow/refresh-tickets
export function edinburghClock(now) {
  const local = new Date(new Date(now).getTime() + BST_OFFSET_MS);
  return { month: local.getUTCMonth() + 1, hour: local.getUTCHours() };
}

// The precondition's verdict as a pure function of the instant — `{ run, reason }`.
export function ticketWindow(now) {
  const { month, hour } = edinburghClock(now);
  const clock = `${String(hour).padStart(2, '0')}:xx Edinburgh, month ${month}`;
  if (month !== FESTIVAL_MONTH) {
    return { run: false, reason: `outside the festival — ${clock}; ticket status only moves during August` };
  }
  // No hour gate: an hours window on a task with one evaluation per slot could
  // only ever silence it.
  return { run: true, reason: `in-festival — ${clock}; refreshing ticket status` };
}

export default {
  id: 'refresh-tickets',
  frequency: 'manual',             // OFF — no occurrence; a hand-created work item is the only way it runs
  schedule_after: ['edfringe/refresh-shows'],
  precondition_signals: [],        // the gate is the calendar, not repo state
  agent_model: 'none',             // pure code; the work is the preprocessing subprocess below
  expected_outcome: 'none',        // it commits refreshed statuses straight to the default branch — no PR
  agent_instructions: 'worker.sh', // vestigial for an agentless task; the real work is the command below
  code_work: 'bash worker.sh',
  code_work_timeout: 900,

  precondition() {
    return ticketWindow(new Date());
  },
};
############ Shepherd/fleet-issues-snapshot
  // next run could collide with it.
  code_work_timeout: 600,
  required_secrets: ['FLEET_GITHUB_TOKEN'], // the account-spanning PAT; fleet-token.mjs states the grant

  // Fire daily unconditionally: the inputs live outside this repo and no signal here
  // can tell whether any of them moved. Cheap to no-op — an unchanged fleet renders
  // the same file and delivers nothing.
  precondition() {
    return { run: true, reason: 'daily fleet issues snapshot — every open issue in every in-scope repo (delivers nothing when unchanged)' };
  },
};
