// edfringe task: refresh-tickets — the in-festival availability refresh,
// currently OFF.
//
// `frequency: 'manual'` is the off switch: a manual task has no occurrence, so
// the scheduler never instantiates it and it runs only from a work item created
// by hand. The site's scraping is off — the owner's call, the festival being
// over — and everything below is intact, so turning it back on is one token.
// `ticketWindow` stays the calendar gate a restored cadence would run under.
//
// Refreshes ticket status for today and every remaining festival date, writing
// through the master so every derived file regenerates from one source (#249).
//
// `schedule_after: ['edfringe/refresh-shows']` rather than a bare cadence anchor:
// it runs after refresh-shows' catalogue top-up, and the two data-committing
// tasks never share a checkout.
//
// `agent_model: 'none'` — the whole job is deterministic, so there is no agent
// and no dispatch issue: the scheduler runs `code_work` as a subprocess and that
// is the entire task. A non-zero exit converges to one open `needs-human` issue.
//
// Self-contained (imports nothing). `edinburghClock` and `ticketWindow` are
// exported beside the declaration so the gate is unit-tested directly
// (window.test.mjs) rather than only reasoned about.

// The calendar gate: the festival month, read on the Edinburgh clock.
export const FESTIVAL_MONTH = 8;

// Europe/London is UTC+1 for the ENTIRE window, so the conversion is a fixed
// one-hour shift and needs no timezone database. British Summer Time runs from
// the last Sunday in March to the last Sunday in October, so August lies strictly
// inside it with months of margin on both sides — there is no DST boundary
// anywhere near this window, and any instant whose Edinburgh wall clock reads
// August is necessarily under BST. (Instants that shift into any other month are
// rejected by the month test regardless, so the offset cannot matter there.)
// The shift is what decides the month at the instants where UTC and Edinburgh
// disagree about it — the last hours of 31 July and 31 August.
const BST_OFFSET_MS = 60 * 60 * 1000;

// The Edinburgh wall-clock month (1–12) and hour (0–23) at UTC instant `now`.
export function edinburghClock(now) {
  const local = new Date(new Date(now).getTime() + BST_OFFSET_MS);
  return { month: local.getUTCMonth() + 1, hour: local.getUTCHours() };
}

// The precondition's verdict as a pure function of the instant — `{ run, reason }`.
=== window.test.mjs:
// Tests for the refresh-tickets precondition gate (task.mjs): August, read on
// the Edinburgh clock. The instants where UTC and Edinburgh disagree about the
// month — the last hours of 31 July and 31 August — are the cases that matter,
// and the fixed +1h shift is cross-checked against the real Europe/London zone
// (via Intl) so the "August is always BST" reasoning is verified, not asserted.

import { test } from "node:test";
import assert from "node:assert/strict";

import { edinburghClock, ticketWindow } from "./task.mjs";

// The real Europe/London wall clock at an instant, straight from the ICU tz data.
const zoned = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Europe/London",
  month: "numeric",
  hour: "numeric",
  hourCycle: "h23",
});
function realEdinburghClock(instant) {
  const parts = Object.fromEntries(zoned.formatToParts(new Date(instant)).map((p) => [p.type, p.value]));
  return { month: Number(parts.month), hour: Number(parts.hour) };
}

// [instant (UTC), should the task run, what the case proves]
const CASES = [
  ["2026-08-15T11:49:00Z", true, "mid-August"],
  ["2026-08-15T02:49:00Z", true, "any hour of an August day passes — an hours gate here would silence the task"],
  ["2026-08-01T04:00:00Z", true, "the first day of the festival"],
  ["2026-08-31T04:00:00Z", true, "the last day of the festival"],
  ["2026-08-31T23:49:00Z", false, "00:49 BST on 1 September — over locally, though UTC still says August"],
  ["2026-07-31T22:49:00Z", false, "23:49 BST on 31 July — still July, however close"],
  ["2026-07-31T23:49:00Z", true, "00:49 BST on 1 August — August locally, though UTC still says July"],
  ["2026-07-15T11:49:00Z", false, "mid-July"],
  ["2026-09-15T11:49:00Z", false, "mid-September"],
  ["2026-01-15T11:49:00Z", false, "mid-January (GMT, not BST)"],
];

test("the refresh-tickets gate fires on August, read on the Edinburgh clock", () => {
  for (const [instant, expected, why] of CASES) {
    const verdict = ticketWindow(instant);
    assert.equal(verdict.run, expected, `${instant} (${why}) — reason was: ${verdict.reason}`);
    assert.ok(verdict.reason.length > 0, `${instant} must carry a reason`);
  }
});

test("the fixed +1h shift matches the real Europe/London clock across the window", () => {
  for (const [instant, , why] of CASES) {
    const real = realEdinburghClock(instant);
    const ours = edinburghClock(instant);
    // Outside BST the fixed shift is deliberately wrong by an hour — the month
    // test rejects those instants anyway, so only the August cases must agree.
    if (real.month !== 8 && ours.month !== 8) continue;
    assert.deepEqual(ours, real, `${instant} (${why}) — Europe/London says ${JSON.stringify(real)}`);
  }
});
