56	// an undeclared pack is skipped rather than rendered greyed-out.
57	//
58	// Two roots, because the same code reads the canon home and a member: the home
59	// runs from the repo root (`packs/<id>`), a member from the mount
60	// (`.claudinite/shared/packs/<id>`), and a local pack — declared `local/<name>` —
61	// from `.claudinite/local/packs/<name>` in both.
62	export function declaredPackDirs(config) {
63	  const dirs = new Map();
64	  for (const entry of config?.packs ?? []) {
65	    const id = typeof entry === 'string' ? entry : entry?.id;
66	    if (!id) continue;
67	    if (id.startsWith('local/')) {
